mapper.select:
SELECT

FROM T_REVENUE_CONTRACT

    IS_DELETED = 0

        AND CONTRACT_NO LIKE '%' || #{param.contractNo} || '%'


        AND CONTRACT_NAME LIKE '%' || #{param.contractName} || '%'


        AND CONTRACT_STATUS = #{param.contractStatus}


        AND CUSTOMER_ID = #{param.customerId}


        AND BOOK_ID = #{param.bookId}


        AND TENANT_ID = #{param.tenantId}


ORDER BY CREATE_TIME DESC

SELECT * FROM ( SELECT CONTRACT_NAME as category, SUM(CONTRACT_AMOUNT) as amount, ROW_NUMBER() OVER (ORDER BY SUM(CONTRACT_AMOUNT) DESC) as rn FROM T_REVENUE_CONTRACT WHERE IS_DELETED = 0
AND SIGN_DATE BETWEEN #{dateRange[0]} AND #{dateRange[1]}
GROUP BY CONTRACT_NAME ) t WHERE t.rn <= 10 ORDER BY t.amount DESC
